function pageInstructor():void{$u=requireUser('instructor');$list=pageQuery('SELECT COUNT(*) FROM courses WHERE instructor_id=?','SELECT c.*,g.name category_name FROM courses c JOIN categories g ON g.id=c.category_id WHERE c.instructor_id=? ORDER BY c.created_at DESC,c.id DESC',[$u['id']]);$cs=$list['rows'];?><main class="container"><?php heading('KHÔNG GIAN GIẢNG DẠY','Khóa học của bạn','Biên soạn bài học và quiz, sau đó xuất bản.');?><a class="btn btn-primary mb-3" href="<?=h(url('edit'))?>">+ Tạo khóa học</a><div class="stats-grid"><?php statCard('Khóa học của bạn',$list['total']);statCard('Tổng enrollment',val('SELECT COUNT(*) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE c.instructor_id=?',[$u['id']]),'Không phải số học viên duy nhất');?></div><div class="panel table-responsive"><table class="table"><thead><tr><th>Khóa học</th><th>Danh mục</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($cs as $c):?><tr><td><strong><?=h($c['title'])?></strong></td><td><?=h($c['category_name'])?></td><td><?=statusBadge($c['status'])?></td><td><a class="btn btn-outline-secondary btn-sm" href="<?=h(url('edit',['id'=>$c['id']]))?>">Quản lý →</a></td></tr><?php endforeach?></tbody></table><?php if(!$cs)emptyState('Chưa có khóa học');pagination($list);?></div></main><?php }
function pageEdit(int $id):void{$u=requireUser('instructor');$c=$id?ownerCourse($id):['id'=>0,'title'=>'','description'=>'','cover_key'=>'default','category_id'=>1,'status'=>'draft'];$tab=(string)($_GET['tab']??'info');if(!in_array($tab,['info','content','quiz','students'],true))$tab='info';$closed=$id&&($c['status']!=='draft'||hasEnrollment($id));?><main class="container"><a href="<?=h(url('instructor'))?>">← Khóa học của bạn</a><?php heading('BIÊN SOẠN KHÓA HỌC',$id?$c['title']:'Tạo bản nháp mới','Lưu từng phần. Rà soát bài học và quiz trước khi xuất bản.');if($id):?><div class="editor-actions"><?=statusBadge($c['status'])?><a class="btn btn-light" href="<?=h(url('preview',['id'=>$id]))?>">Xem trước</a><?php foreach(($c['status']==='draft'?['published']:($c['status']==='published'?['draft','archived']:['published'])) as $target):echo formStart('course_state',['course_id'=>$id,'target'=>$target,'return_page'=>'edit']);echo confirmField();?><button class="btn btn-outline-secondary btn-sm"><?=h(['published'=>'Xuất bản','draft'=>'Về nháp','archived'=>'Lưu trữ'][$target])?></button></form><?php endforeach;if(!$closed):echo formStart('course_delete',['course_id'=>$id,'return_page'=>'edit']);echo confirmField();?><button class="btn btn-outline-danger btn-sm">Xóa nháp</button></form><?php endif?></div><nav class="tabs"><?php foreach(['info'=>'Thông tin','content'=>'Nội dung','quiz'=>'Quiz cuối khóa','students'=>'Học viên'] as $v=>$label):?><a class="<?=$tab===$v?'active':''?>" href="<?=h(url('edit',['id'=>$id,'tab'=>$v]))?>"><?=h($label)?></a><?php endforeach?></nav><?php endif;
 if(!$id||$tab==='info'):?><section class="panel editor-form"><h2>Thông tin khóa học</h2><?=formStart('course_save',['course_id'=>$id,'return_page'=>'edit'])?><?php field('title','Tên khóa học',$c['title'],'text','required minlength="5" maxlength="150"');area('description','Mô tả',$c['description'],'required minlength="20" maxlength="2000" rows="4"');?><div class="form-grid"><label>Danh mục<select class="form-select" name="category_id"><?php foreach(all('SELECT * FROM categories ORDER BY name') as $cat):?><option value="<?=$cat['id']?>" <?=(int)$c['category_id']===(int)$cat['id']?'selected':''?>><?=h($cat['name'])?></option><?php endforeach?></select></label><label>Ảnh bìa có sẵn<select class="form-select" name="cover_key"><?php foreach(['default','web','programming','database'] as $key):?><option <?=$key===$c['cover_key']?'selected':''?>><?=h($key)?></option><?php endforeach?></select></label></div><button class="btn btn-primary">Lưu thông tin</button></form></section><?php
 elseif($tab==='content'):
 $chapters=all('SELECT * FROM chapters WHERE course_id=? ORDER BY position,id',[$id]);$editLesson=null;if(isset($_GET['lesson'])){$editLesson=lessonCourse((int)$_GET['lesson']);if((int)$editLesson['course_id']!==$id)reject('Bài không thuộc khóa.',404);}
 ?><p class="alert alert-light"><?=$closed?'Cấu trúc đã đóng. Chỉ sửa trình bày; không đổi mục tiêu kiến thức.':'Bản nháp chưa enrollment được thêm/xóa/đổi thứ tự.'?></p><div class="content-editor-grid"><section class="panel"><h2>Chapter và lesson</h2><?php foreach($chapters as $ch):?><section class="chapter-editor"><h3><?=$ch['position']?>. <?=h($ch['title'])?></h3><?=formStart('chapter_save',['course_id'=>$id,'chapter_id'=>$ch['id'],'return_page'=>'edit','return_tab'=>'content'])?><div class="form-grid"><?php field('title','Tên chương',$ch['title'],'text','required minlength="2" maxlength="150"');field('position','Thứ tự',(string)$ch['position'],'number','min="1" required '.($closed?'readonly':''));?></div><button class="btn btn-light btn-sm">Lưu chương</button></form><?php if(!$closed):echo formStart('chapter_delete',['course_id'=>$id,'chapter_id'=>$ch['id'],'return_page'=>'edit','return_tab'=>'content']);echo confirmField();?><button class="btn btn-outline-danger btn-sm">Xóa chương</button></form><?php endif;foreach(all('SELECT * FROM lessons WHERE chapter_id=? ORDER BY position,id',[$ch['id']]) as $l):?><div class="content-row"><span><?=$l['position']?>. <?=h($l['title'])?></span><div class="flex gap"><a class="btn btn-light btn-sm" href="<?=h(url('preview',['id'=>$id,'lesson'=>$l['id']]))?>">Xem</a><a class="btn btn-light btn-sm" href="<?=h(url('edit',['id'=>$id,'tab'=>'content','lesson'=>$l['id']]))?>">Sửa</a></div></div><?php if(!$closed):echo formStart('lesson_delete',['course_id'=>$id,'lesson_id'=>$l['id'],'return_page'=>'edit','return_tab'=>'content']);echo confirmField();?><button class="btn btn-outline-danger btn-sm">Xóa bài</button></form><?php endif;endforeach?></section><?php endforeach;if(!$closed):echo formStart('chapter_save',['course_id'=>$id,'return_page'=>'edit','return_tab'=>'content']);field('title','Tên chương mới','','text','required minlength="2" maxlength="150"');field('position','Thứ tự',(string)(count($chapters)+1),'number','min="1" required');?><button class="btn btn-outline-secondary">+ Thêm chương</button></form><?php endif?></section><section class="panel"><h2><?=$editLesson?'Sửa bài học':'Thêm bài học'?></h2><?php if(!$closed||$editLesson):echo formStart('lesson_save',['course_id'=>$id,'lesson_id'=>$editLesson['id']??0,'return_page'=>'edit','return_tab'=>'content']);if(!$editLesson):?><label>Chương<select class="form-select" name="chapter_id" required><option value="">Chọn chương</option><?php foreach($chapters as $ch):?><option value="<?=$ch['id']?>"><?=h($ch['title'])?></option><?php endforeach?></select></label><?php endif;field('title','Tiêu đề',$editLesson['title']??'','text','required minlength="2" maxlength="150"');area('body','Nội dung Markdown',$editLesson['body']??'','required minlength="50" maxlength="12000" rows="10"');field('position','Thứ tự',(string)($editLesson['position']??1),'number','min="1" required '.($closed?'readonly':''));field('youtube_video_id','YouTube ID tùy chọn',$editLesson['youtube_video_id']??'','text','pattern="[A-Za-z0-9_-]{11}" maxlength="11"');?><button class="btn btn-primary">Lưu bài học</button></form><?php else:emptyState('Chỉ sửa bài đã có','Chọn Sửa ở danh sách bên trái.');endif?></section></div><?php
 elseif($tab==='quiz'):
 $questions=questionsFor($id);$n=max(5,min(20,(int)($_GET['count']??count($questions))));if(!$closed)while(count($questions)<$n)$questions[]=['prompt'=>'','explanation'=>'','answers'=>array_fill(0,4,['text'=>'','is_correct'=>0])];if(!$closed)$questions=array_slice($questions,0,$n);
 ?><p class="alert alert-light">5–20 câu · bốn lựa chọn/câu · một đáp án đúng · đạt từ 70%. <?=$closed?'Quiz đã khóa, chỉ xem.':'Lưu toàn bộ quiz trong một transaction.'?></p><?php if(!$closed):?><form method="get" action="/index.php" class="panel mb-3"><?=hidden('page','edit').hidden('id',$id).hidden('tab','quiz')?><?php field('count','Số câu hỏi',(string)$n,'number','min="5" max="20" required');?><p class="small muted">Lưu quiz hiện tại trước khi đổi số câu; lựa chọn này tải lại form.</p><button class="btn btn-light">Áp dụng số câu</button></form><?=formStart('quiz_save',['course_id'=>$id,'return_page'=>'edit','return_tab'=>'quiz'])?><?php endif;foreach($questions as $i=>$q):?><fieldset class="panel question" <?=$closed?'disabled':''?>><legend>Câu <?=$i+1?></legend><label>Câu hỏi<input class="form-control" name="questions[<?=$i?>][prompt]" value="<?=h($q['prompt'])?>" required minlength="5" maxlength="500"></label><?php foreach($q['answers'] as $j=>$answer):?><div class="quiz-builder-option"><label class="correct-radio"><input type="radio" name="questions[<?=$i?>][correct]" value="<?=$j?>" <?=$answer['is_correct']?'checked':''?> required> Đúng</label><input class="form-control" aria-label="Lựa chọn <?=chr(65+$j)?> câu <?=$i+1?>" name="questions[<?=$i?>][answers][<?=$j?>]" value="<?=h($answer['text'])?>" required maxlength="250"></div><?php endforeach?><label>Giải thích<textarea class="form-control" name="questions[<?=$i?>][explanation]" maxlength="1000"><?=h($q['explanation'])?></textarea></label></fieldset><?php endforeach;if(!$closed):?><button class="btn btn-primary">Lưu toàn bộ quiz</button></form><?php endif;
 elseif($tab==='students'):
 $list=pageQuery('SELECT COUNT(*) FROM enrollments e WHERE e.course_id=?','SELECT e.*,u.name,COALESCE(totals.total,0) total,COALESCE(done.done,0) done,scores.best FROM enrollments e JOIN users u ON u.id=e.user_id '.progressJoins().' WHERE e.course_id=? ORDER BY e.created_at DESC,e.id DESC',[$id]);$rows=$list['rows'];?><section class="panel table-responsive"><h2>Học viên của khóa</h2><table class="table"><thead><tr><th>Họ tên</th><th>Tiến độ</th><th>Điểm tốt nhất</th><th>Hoàn thành</th></tr></thead><tbody><?php foreach($rows as $e):$p=rowProgress($e);?><tr><td><?=h($e['name'])?></td><td><?=$p['percent']?>%</td><td><?=h($p['best']??'—')?></td><td><?=$e['completed_at']?'Có':'Chưa'?></td></tr><?php endforeach?></tbody></table><?php if(!$rows)emptyState('Chưa có học viên');pagination($list);?></section><?php endif?></main><?php }
function pagePreview(int $id):void{$u=requireUser();$c=$u['role']==='admin'?getCourse($id):ownerCourse($id);?><main class="container"><a href="<?=h(url($u['role']==='admin'?'admin':'edit',$u['role']==='admin'?['tab'=>'courses']:['id'=>$id]))?>">← Về quản lý</a><?php heading('XEM TRƯỚC CHỈ ĐỌC',$c['title'],'Không tạo enrollment, progress hoặc attempt.');?><div class="panel"><?php if(isset($_GET['lesson'])){$l=lessonCourse((int)$_GET['lesson']);if((int)$l['course_id']!==$id)reject('Bài không thuộc khóa.',404);lessonViewer($l);}else{foreach(courseLessons($id) as $l)echo '<p><a href="'.h(url('preview',['id'=>$id,'lesson'=>$l['id']])).'">'.h($l['title']).' →</a></p>';echo '<h2>Quiz và đáp án cho quản lý</h2>';foreach(questionsFor($id) as $q){echo '<h3>'.h($q['prompt']).'</h3><ul>';foreach($q['answers'] as $a)echo '<li>'.h($a['text']).($a['is_correct']?' ✓':'').'</li>';echo '</ul>';}}?></div></main><?php }
function pageAdmin():void{
 requireUser('admin');$tab=(string)($_GET['tab']??'users');if(!in_array($tab,['users','courses','categories'],true))$tab='users';
 $q=searchQuery();$pattern=searchPattern($q);
 if($tab==='users'){$where="name LIKE ? ESCAPE '!' OR email LIKE ? ESCAPE '!'";$params=[$pattern,$pattern];$table='users';}
 elseif($tab==='courses'){$where="title LIKE ? ESCAPE '!'";$params=[$pattern];$table='courses';}
 else{$where="name LIKE ? ESCAPE '!'";$params=[$pattern];$table='categories';}
 $list=pageQuery('SELECT COUNT(*) FROM '.$table.' WHERE '.$where,'SELECT * FROM '.$table.' WHERE '.$where.' ORDER BY id DESC',$params);
 ?><main class="container"><?php heading('QUẢN TRỊ HỆ THỐNG','Tổng quan StudyMate','Quản lý tài khoản, trạng thái khóa học và danh mục.');?><div class="stats-grid"><?php statCard('Người dùng',val('SELECT COUNT(*) FROM users'));statCard('Tổng khóa học',val('SELECT COUNT(*) FROM courses'));statCard('Đã xuất bản',val("SELECT COUNT(*) FROM courses WHERE status='published'"));?></div><nav class="tabs"><?php foreach(['users'=>'Người dùng','courses'=>'Khóa học','categories'=>'Danh mục'] as $v=>$name):?><a class="<?=$v===$tab?'active':''?>" href="<?=h(url('admin',['tab'=>$v]))?>"><?=h($name)?></a><?php endforeach?></nav>
 <form class="filter-bar" method="get"><?=hidden('page','admin').hidden('tab',$tab)?><?php field('q','Tìm tên hoặc email',$q,'text','maxlength="100"');?><button class="btn btn-primary">Tìm</button></form>
 <section class="panel table-responsive"><table class="table"><thead><tr><th><?=$tab==='users'?'Người dùng':($tab==='courses'?'Khóa học':'Danh mục')?></th><th>Trạng thái / vai trò</th><th>Thao tác</th></tr></thead><tbody>
 <?php foreach($list['rows'] as $row):?><tr><?php if($tab==='users'):?><td><strong><?=h($row['name'])?></strong><small class="block muted"><?=h($row['email'])?></small></td><td><?=h($row['role'])?> · <?=$row['is_active']?'Hoạt động':'Đã khóa'?></td><td><?php if($row['role']!=='admin'):echo formStart('user_status',['user_id'=>$row['id'],'is_active'=>$row['is_active']?0:1,'return_page'=>'admin']);echo confirmField();?><button class="btn btn-outline-secondary"><?=$row['is_active']?'Khóa':'Mở khóa'?></button></form><?php else:echo 'Không cho khóa Admin';endif?></td>
 <?php elseif($tab==='courses'):?><td><?=h($row['title'])?></td><td><?=statusBadge($row['status'])?></td><td><a class="btn btn-light" href="<?=h(url('preview',['id'=>$row['id']]))?>">Xem trước</a><?php if($row['status']==='published'):echo formStart('course_state',['course_id'=>$row['id'],'target'=>'archived','return_page'=>'admin','return_tab'=>'courses']);echo confirmField();?><button class="btn btn-outline-secondary">Lưu trữ</button></form><?php endif?></td>
 <?php else:?><td><?=formStart('category_save',['category_id'=>$row['id'],'return_page'=>'admin','return_tab'=>'categories'])?><?php field('name','Tên danh mục',$row['name'],'text','required minlength="2" maxlength="80"');?><button class="btn btn-light">Lưu</button></form></td><td>Danh mục</td><td><?=formStart('category_delete',['category_id'=>$row['id'],'return_page'=>'admin','return_tab'=>'categories'])?><?=confirmField()?><button class="btn btn-outline-danger">Xóa</button></form></td><?php endif?></tr><?php endforeach?></tbody></table>
 <?php if(!$list['rows'])emptyState('Không có kết quả phù hợp','Thử thay đổi nội dung tìm kiếm.');pagination($list);?></section>
 <?php if($tab==='categories'):?><section class="panel mt-3"><h2>Thêm danh mục</h2><?=formStart('category_save',['return_page'=>'admin','return_tab'=>'categories'])?><?php field('name','Tên danh mục mới','','text','required minlength="2" maxlength="80"');?><button class="btn btn-primary">Thêm danh mục</button></form></section><?php endif?></main><?php }
